import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_22_curriculum_overview.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_22_task_distribution.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_22_difficulty_band.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_22_reverse_curriculum.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_22_driving_curriculum.png",f=JSON.parse('{"title":"任务太难学不会？课程学习如何把成功区域一步步推远","description":"稀疏奖励的困难不只来自奖励函数，还来自初始状态和任务难度。如果智能体一开始就被放进几乎不可能成功的环境，探索、价值传播和策略更新都没有可靠信号。Curriculum Learning（课程学习）把训练任务组织成由易到难的序列，让智能体先学会局部技能，再逐步扩大能力范围；Reverse Curricu","frontmatter":{"title":"任务太难学不会？课程学习如何把成功区域一步步推远","description":"稀疏奖励的困难不只来自奖励函数，还来自初始状态和任务难度。如果智能体一开始就被放进几乎不可能成功的环境，探索、价值传播和策略更新都没有可靠信号。Curriculum Learning（课程学习）把训练任务组织成由易到难的序列，让智能体先学会局部技能，再逐步扩大能力范围；Reverse Curricu","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":8,"source":"2026-08-13/rl_series_22_curriculum_learning.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_22_curriculum_overview.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-22-curriculum-learning"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"任务太难学不会？课程学习如何把成功区域一步步推远"}],["meta",{"property":"og:description","content":"稀疏奖励的困难不只来自奖励函数，还来自初始状态和任务难度。如果智能体一开始就被放进几乎不可能成功的环境，探索、价值传播和策略更新都没有可靠信号。Curriculum Learning（课程学习）把训练任务组织成由易到难的序列，让智能体先学会局部技能，再逐步扩大能力范围；Reverse Curricu"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-22-curriculum-learning"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_22_curriculum_overview.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"任务太难学不会？课程学习如何把成功区域一步步推远"}],["meta",{"name":"twitter:description","content":"稀疏奖励的困难不只来自奖励函数，还来自初始状态和任务难度。如果智能体一开始就被放进几乎不可能成功的环境，探索、价值传播和策略更新都没有可靠信号。Curriculum Learning（课程学习）把训练任务组织成由易到难的序列，让智能体先学会局部技能，再逐步扩大能力范围；Reverse Curricu"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_22_curriculum_overview.png"}]],"prev":{"text":"越意外越值得探索吗？ICM、RND 与“噪声电视”陷阱","link":"/rl/rl-series-21-intrinsic-curiosity-icm"},"next":{"text":"失败也能变经验：目标条件强化学习与 HER 讲透了","link":"/rl/rl-series-23-her-goal-conditioned-rl"}},"headers":[],"relativePath":"rl/rl-series-22-curriculum-learning.md","filePath":"rl/rl-series-22-curriculum-learning.md","lastUpdated":null}'),c={name:"rl/rl-series-22-curriculum-learning.md"};function u(d,a,p,_,b,m){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="任务太难学不会-课程学习如何把成功区域一步步推远" tabindex="-1">任务太难学不会？课程学习如何把成功区域一步步推远 <a class="header-anchor" href="#任务太难学不会-课程学习如何把成功区域一步步推远" aria-label="Permalink to &quot;任务太难学不会？课程学习如何把成功区域一步步推远&quot;">​</a></h1><p>稀疏奖励的困难不只来自奖励函数，还来自初始状态和任务难度。如果智能体一开始就被放进几乎不可能成功的环境，探索、价值传播和策略更新都没有可靠信号。Curriculum Learning（课程学习）把训练任务组织成由易到难的序列，让智能体先学会局部技能，再逐步扩大能力范围；Reverse Curriculum Generation（逆向课程生成）则从一个已知成功状态附近反向扩张起始状态。</p><p>课程不是简单地把回合长度调大，也不是把奖励偷偷改稠密。它改变的是训练分布：哪些初始状态被采样、哪些环境参数出现、哪些任务被安排给当前策略。好的课程应当让样本处于“可学但不已学会”的区域，同时避免过拟合单一场景、课程跳变和评估污染。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-课程学习改变任务分布" tabindex="-1">1.1 课程学习改变任务分布 <a class="header-anchor" href="#_1-1-课程学习改变任务分布" aria-label="Permalink to &quot;1.1 课程学习改变任务分布&quot;">​</a></h3><p>策略、奖励和网络可以不变，只改变初始状态、障碍密度、目标距离或动力学参数，学习难度就会改变。</p><h3 id="_1-2-太简单和太困难都不是好课程" tabindex="-1">1.2 太简单和太困难都不是好课程 <a class="header-anchor" href="#_1-2-太简单和太困难都不是好课程" aria-label="Permalink to &quot;1.2 太简单和太困难都不是好课程&quot;">​</a></h3><p>全成功意味着没有新的学习压力，全失败意味着没有有效梯度。课程应持续提供有区分度的反馈。</p><h3 id="_1-3-逆向课程从目标附近开始" tabindex="-1">1.3 逆向课程从目标附近开始 <a class="header-anchor" href="#_1-3-逆向课程从目标附近开始" aria-label="Permalink to &quot;1.3 逆向课程从目标附近开始&quot;">​</a></h3><p>如果能重置到一个已完成或接近完成的状态，就先学习从附近状态到目标，再逐渐把起始状态推远。</p><h3 id="_1-4-课程能力不等于最终泛化" tabindex="-1">1.4 课程能力不等于最终泛化 <a class="header-anchor" href="#_1-4-课程能力不等于最终泛化" aria-label="Permalink to &quot;1.4 课程能力不等于最终泛化&quot;">​</a></h3><p>课程训练成功只说明策略适应了训练分布。必须在未见难度、不同初始状态和扰动条件下独立评估。</p><p><img src="'+l+'" alt="课程学习把任务难度从可学区域逐步推向完整任务"></p><h2 id="二、为什么直接训练完整任务容易失败" tabindex="-1">二、为什么直接训练完整任务容易失败 <a class="header-anchor" href="#二、为什么直接训练完整任务容易失败" aria-label="Permalink to &quot;二、为什么直接训练完整任务容易失败&quot;">​</a></h2><h3 id="_2-1-成功轨迹概率随任务长度下降" tabindex="-1">2.1 成功轨迹概率随任务长度下降 <a class="header-anchor" href="#_2-1-成功轨迹概率随任务长度下降" aria-label="Permalink to &quot;2.1 成功轨迹概率随任务长度下降&quot;">​</a></h3><p>需要连续完成多个子目标时，任一步失败都会让终点奖励消失。随机探索很难偶然走完整条路径。</p><h3 id="_2-2-价值函数先看到的几乎全是失败" tabindex="-1">2.2 价值函数先看到的几乎全是失败 <a class="header-anchor" href="#_2-2-价值函数先看到的几乎全是失败" aria-label="Permalink to &quot;2.2 价值函数先看到的几乎全是失败&quot;">​</a></h3><p>回放池由相似失败转移组成，评论家无法建立目标进展与动作的区分，演员或 Q-learning 只能追逐近似误差。</p><h3 id="_2-3-复杂动力学放大早期错误" tabindex="-1">2.3 复杂动力学放大早期错误 <a class="header-anchor" href="#_2-3-复杂动力学放大早期错误" aria-label="Permalink to &quot;2.3 复杂动力学放大早期错误&quot;">​</a></h3><p>高速度、强扰动或长控制延迟会让一个小动作误差迅速变成不可恢复状态。此时失败样本并不能告诉策略如何修正。</p><h3 id="_2-4-增加网络容量不能创造成功经验" tabindex="-1">2.4 增加网络容量不能创造成功经验 <a class="header-anchor" href="#_2-4-增加网络容量不能创造成功经验" aria-label="Permalink to &quot;2.4 增加网络容量不能创造成功经验&quot;">​</a></h3><p>模型表达能力解决的是拟合问题，不解决数据分布里没有目标事件的问题。课程首先要改善可获得的学习信号。</p><h2 id="三、课程学习到底在改变哪些变量" tabindex="-1">三、课程学习到底在改变哪些变量 <a class="header-anchor" href="#三、课程学习到底在改变哪些变量" aria-label="Permalink to &quot;三、课程学习到底在改变哪些变量&quot;">​</a></h2><h3 id="_3-1-改变初始状态分布" tabindex="-1">3.1 改变初始状态分布 <a class="header-anchor" href="#_3-1-改变初始状态分布" aria-label="Permalink to &quot;3.1 改变初始状态分布&quot;">​</a></h3><p>可以从更接近目标的位置开始，再逐步扩大初始距离、姿态误差或路线范围。</p><h3 id="_3-2-改变环境参数" tabindex="-1">3.2 改变环境参数 <a class="header-anchor" href="#_3-2-改变环境参数" aria-label="Permalink to &quot;3.2 改变环境参数&quot;">​</a></h3><p>障碍数量、摩擦系数、传感器噪声、交通密度和动力学延迟都可以作为课程轴，但每个参数都需要定义可行范围。</p><h3 id="_3-3-改变目标复杂度" tabindex="-1">3.3 改变目标复杂度 <a class="header-anchor" href="#_3-3-改变目标复杂度" aria-label="Permalink to &quot;3.3 改变目标复杂度&quot;">​</a></h3><p>先完成单个子目标，再加入顺序约束、动态障碍和多目标切换。目标条件任务尤其适合这种安排。</p><h3 id="_3-4-改变教师采样策略" tabindex="-1">3.4 改变教师采样策略 <a class="header-anchor" href="#_3-4-改变教师采样策略" aria-label="Permalink to &quot;3.4 改变教师采样策略&quot;">​</a></h3><p>课程可以由人工规则指定，也可以由教师根据成功率、学习进度或策略不确定性选择下一批任务。</p><p><img src="'+o+'" alt="课程参数、学生策略与任务难度的闭环"></p><h2 id="四、怎样定义-可学但不太容易-的区域" tabindex="-1">四、怎样定义“可学但不太容易”的区域 <a class="header-anchor" href="#四、怎样定义-可学但不太容易-的区域" aria-label="Permalink to &quot;四、怎样定义“可学但不太容易”的区域&quot;">​</a></h2><h3 id="_4-1-用成功率而不是单次结果判断" tabindex="-1">4.1 用成功率而不是单次结果判断 <a class="header-anchor" href="#_4-1-用成功率而不是单次结果判断" aria-label="Permalink to &quot;4.1 用成功率而不是单次结果判断&quot;">​</a></h3><p>单个回合成功可能是偶然。应在固定窗口内统计成功率、碰撞率、超时率和完成时间。</p><h3 id="_4-2-保留中等难度任务" tabindex="-1">4.2 保留中等难度任务 <a class="header-anchor" href="#_4-2-保留中等难度任务" aria-label="Permalink to &quot;4.2 保留中等难度任务&quot;">​</a></h3><p>成功率接近零的任务暂时过难，接近一的任务已经掌握。课程采样应更多集中在中间区域。</p><h3 id="_4-3-监控学习进度而不是只看回报" tabindex="-1">4.3 监控学习进度而不是只看回报 <a class="header-anchor" href="#_4-3-监控学习进度而不是只看回报" aria-label="Permalink to &quot;4.3 监控学习进度而不是只看回报&quot;">​</a></h3><p>如果成功率没有上升但 Q 值上升，可能是价值高估；如果成功率上升后立即坠落，可能是课程跳跃或遗忘。</p><h3 id="_4-4-课程门槛必须可回退" tabindex="-1">4.4 课程门槛必须可回退 <a class="header-anchor" href="#_4-4-课程门槛必须可回退" aria-label="Permalink to &quot;4.4 课程门槛必须可回退&quot;">​</a></h3><p>当策略在新难度上退化时，应保留旧难度的复习样本或降低难度，而不是强行继续推进。</p><p><img src="'+h+'" alt="课程难度带：把样本保持在可学但不太容易的区域"></p><h2 id="五、逆向课程生成怎样从目标反推" tabindex="-1">五、逆向课程生成怎样从目标反推 <a class="header-anchor" href="#五、逆向课程生成怎样从目标反推" aria-label="Permalink to &quot;五、逆向课程生成怎样从目标反推&quot;">​</a></h2><h3 id="_5-1-需要一个已知目标状态" tabindex="-1">5.1 需要一个已知目标状态 <a class="header-anchor" href="#_5-1-需要一个已知目标状态" aria-label="Permalink to &quot;5.1 需要一个已知目标状态&quot;">​</a></h3><p>目标状态可以由人工设置、规划器生成或成功轨迹得到。它不要求策略已经会从远处到达目标。</p><h3 id="_5-2-在目标附近采样起始状态" tabindex="-1">5.2 在目标附近采样起始状态 <a class="header-anchor" href="#_5-2-在目标附近采样起始状态" aria-label="Permalink to &quot;5.2 在目标附近采样起始状态&quot;">​</a></h3><p>从目标状态施加小位置、姿态或物体扰动，让策略学习短距离恢复。成功轨迹提供清晰的正向信号。</p><h3 id="_5-3-根据可达性向外扩张" tabindex="-1">5.3 根据可达性向外扩张 <a class="header-anchor" href="#_5-3-根据可达性向外扩张" aria-label="Permalink to &quot;5.3 根据可达性向外扩张&quot;">​</a></h3><p>对能稳定成功的起始状态邻域继续向外采样，对太难或太简单的状态降低权重。</p><h3 id="_5-4-逆向扩张依赖重置能力" tabindex="-1">5.4 逆向扩张依赖重置能力 <a class="header-anchor" href="#_5-4-逆向扩张依赖重置能力" aria-label="Permalink to &quot;5.4 逆向扩张依赖重置能力&quot;">​</a></h3><p>真实车辆难以任意重置到危险道路状态，因此该方法更适合仿真、机械臂或可控测试场。重置器本身也需要验证。</p><p><img src="'+n+'" alt="逆向课程从目标状态向外扩张起始状态"></p><h2 id="六、课程中的常见失效模式" tabindex="-1">六、课程中的常见失效模式 <a class="header-anchor" href="#六、课程中的常见失效模式" aria-label="Permalink to &quot;六、课程中的常见失效模式&quot;">​</a></h2><h3 id="_6-1-只会单一目标点" tabindex="-1">6.1 只会单一目标点 <a class="header-anchor" href="#_6-1-只会单一目标点" aria-label="Permalink to &quot;6.1 只会单一目标点&quot;">​</a></h3><p>策略可能过拟合一个目标位置，换目标、换地图或换初始姿态就失败。课程需要覆盖目标集合而不是单点。</p><h3 id="_6-2-难度跳跃造成灾难性遗忘" tabindex="-1">6.2 难度跳跃造成灾难性遗忘 <a class="header-anchor" href="#_6-2-难度跳跃造成灾难性遗忘" aria-label="Permalink to &quot;6.2 难度跳跃造成灾难性遗忘&quot;">​</a></h3><p>一次提高太多障碍或噪声，策略会丢失已学技能。混合旧课程回放可以缓解，但会增加采样管理复杂度。</p><h3 id="_6-3-教师依据有偏指标选任务" tabindex="-1">6.3 教师依据有偏指标选任务 <a class="header-anchor" href="#_6-3-教师依据有偏指标选任务" aria-label="Permalink to &quot;6.3 教师依据有偏指标选任务&quot;">​</a></h3><p>只按回报挑任务可能把奖励投机误认为能力。教师应结合真实成功、约束违例和动作质量。</p><h3 id="_6-4-训练课程泄漏到测试集" tabindex="-1">6.4 训练课程泄漏到测试集 <a class="header-anchor" href="#_6-4-训练课程泄漏到测试集" aria-label="Permalink to &quot;6.4 训练课程泄漏到测试集&quot;">​</a></h3><p>如果测试难度参与课程选择，最终性能会被高估。课程教师只能访问训练反馈，测试环境应完全隔离。</p><h2 id="七、自动驾驶中如何设计课程轴" tabindex="-1">七、自动驾驶中如何设计课程轴 <a class="header-anchor" href="#七、自动驾驶中如何设计课程轴" aria-label="Permalink to &quot;七、自动驾驶中如何设计课程轴&quot;">​</a></h2><h3 id="_7-1-从低速、低扰动和简单道路开始" tabindex="-1">7.1 从低速、低扰动和简单道路开始 <a class="header-anchor" href="#_7-1-从低速、低扰动和简单道路开始" aria-label="Permalink to &quot;7.1 从低速、低扰动和简单道路开始&quot;">​</a></h3><p>先验证状态、动作、终止和安全监控接口，再逐步加入曲率、延迟、动态障碍和传感器噪声。</p><h3 id="_7-2-不把安全约束当成难度开关" tabindex="-1">7.2 不把安全约束当成难度开关 <a class="header-anchor" href="#_7-2-不把安全约束当成难度开关" aria-label="Permalink to &quot;7.2 不把安全约束当成难度开关&quot;">​</a></h3><p>任何课程阶段都应保留碰撞检测、动作限幅和备用控制。简单场景也不能关闭安全层。</p><h3 id="_7-3-课程应覆盖长尾而非只追求成功率" tabindex="-1">7.3 课程应覆盖长尾而非只追求成功率 <a class="header-anchor" href="#_7-3-课程应覆盖长尾而非只追求成功率" aria-label="Permalink to &quot;7.3 课程应覆盖长尾而非只追求成功率&quot;">​</a></h3><p>训练后期要主动加入低频但关键的施工区、遮挡、低附着和控制延迟场景，并独立报告各类场景指标。</p><p><img src="'+s+'" alt="自动驾驶课程从基础跟踪到长尾扰动的安全分层"></p><h2 id="八、一个最小实验怎样设计" tabindex="-1">八、一个最小实验怎样设计 <a class="header-anchor" href="#八、一个最小实验怎样设计" aria-label="Permalink to &quot;八、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_8-1-建立完整任务和分级任务" tabindex="-1">8.1 建立完整任务和分级任务 <a class="header-anchor" href="#_8-1-建立完整任务和分级任务" aria-label="Permalink to &quot;8.1 建立完整任务和分级任务&quot;">​</a></h3><p>以二维目标导航或简化车道保持为例，设置目标距离、障碍数量和动力学扰动三个课程轴。</p><h3 id="_8-2-比较直接训练与课程训练" tabindex="-1">8.2 比较直接训练与课程训练 <a class="header-anchor" href="#_8-2-比较直接训练与课程训练" aria-label="Permalink to &quot;8.2 比较直接训练与课程训练&quot;">​</a></h3><p>保持算法、环境步数、网络和随机种子一致，比较首次成功步数、最终泛化和失败类型。</p><h3 id="_8-3-比较正向课程与逆向课程" tabindex="-1">8.3 比较正向课程与逆向课程 <a class="header-anchor" href="#_8-3-比较正向课程与逆向课程" aria-label="Permalink to &quot;8.3 比较正向课程与逆向课程&quot;">​</a></h3><p>逆向课程从目标附近初始化，正向课程从简单环境逐步增加难度，分别记录重置成本和策略覆盖范围。</p><h3 id="_8-4-做课程消融" tabindex="-1">8.4 做课程消融 <a class="header-anchor" href="#_8-4-做课程消融" aria-label="Permalink to &quot;8.4 做课程消融&quot;">​</a></h3><p>移除回退机制、旧任务复习或长尾场景采样，观察策略是否遗忘和安全指标是否恶化。</p><h2 id="九、最常见的实现错误" tabindex="-1">九、最常见的实现错误 <a class="header-anchor" href="#九、最常见的实现错误" aria-label="Permalink to &quot;九、最常见的实现错误&quot;">​</a></h2><h3 id="_9-1-用训练成功率代替最终性能" tabindex="-1">9.1 用训练成功率代替最终性能 <a class="header-anchor" href="#_9-1-用训练成功率代替最终性能" aria-label="Permalink to &quot;9.1 用训练成功率代替最终性能&quot;">​</a></h3><p>课程内成功率只反映当前采样分布，不能代替固定测试集表现。</p><h3 id="_9-2-课程阶段之间改变评价标准" tabindex="-1">9.2 课程阶段之间改变评价标准 <a class="header-anchor" href="#_9-2-课程阶段之间改变评价标准" aria-label="Permalink to &quot;9.2 课程阶段之间改变评价标准&quot;">​</a></h3><p>如果不同阶段的成功定义不同，曲线无法直接比较。任务指标应保持语义稳定。</p><h3 id="_9-3-只保存当前课程数据" tabindex="-1">9.3 只保存当前课程数据 <a class="header-anchor" href="#_9-3-只保存当前课程数据" aria-label="Permalink to &quot;9.3 只保存当前课程数据&quot;">​</a></h3><p>没有旧难度回放时，策略容易遗忘基础技能，特别是在连续参数环境中。</p><h3 id="_9-4-把逆向课程当成奖励塑形" tabindex="-1">9.4 把逆向课程当成奖励塑形 <a class="header-anchor" href="#_9-4-把逆向课程当成奖励塑形" aria-label="Permalink to &quot;9.4 把逆向课程当成奖励塑形&quot;">​</a></h3><p>逆向课程改变起始状态分布，不一定改变奖励函数。两者的因果作用和评价方法不同。</p><h2 id="十、学到什么程度才算掌握" tabindex="-1">十、学到什么程度才算掌握 <a class="header-anchor" href="#十、学到什么程度才算掌握" aria-label="Permalink to &quot;十、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_10-1-能区分任务分布和奖励函数" tabindex="-1">10.1 能区分任务分布和奖励函数 <a class="header-anchor" href="#_10-1-能区分任务分布和奖励函数" aria-label="Permalink to &quot;10.1 能区分任务分布和奖励函数&quot;">​</a></h3><p>你应能说明课程可以不改奖励而改变学习难度，也能指出课程与奖励塑形可同时使用但必须分别审计。</p><h3 id="_10-2-能设计可回退的难度调度" tabindex="-1">10.2 能设计可回退的难度调度 <a class="header-anchor" href="#_10-2-能设计可回退的难度调度" aria-label="Permalink to &quot;10.2 能设计可回退的难度调度&quot;">​</a></h3><p>你应能用成功率、失败类型和泛化指标决定升阶、保持或回退。</p><h3 id="_10-3-能解释逆向课程的重置边界" tabindex="-1">10.3 能解释逆向课程的重置边界 <a class="header-anchor" href="#_10-3-能解释逆向课程的重置边界" aria-label="Permalink to &quot;10.3 能解释逆向课程的重置边界&quot;">​</a></h3><p>你应能判断任务是否允许任意重置，以及重置器是否引入训练—部署差异。</p><h3 id="_10-4-能进入-her" tabindex="-1">10.4 能进入 HER <a class="header-anchor" href="#_10-4-能进入-her" aria-label="Permalink to &quot;10.4 能进入 HER&quot;">​</a></h3><p>课程解决“从哪里开始学”，下一篇将讨论失败轨迹如何通过替代目标变成有效经验。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter10/chapter10.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十章课程学习与逆向课程部分</a></p><p><a href="https://arxiv.org/abs/1707.05300" target="_blank" rel="noreferrer">Florensa 等《Reverse Curriculum Generation for Reinforcement Learning》</a></p><p><a href="http://incompleteideas.net/book/the-book-2nd.html" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction》第二版</a></p>',100)])])}const k=e(c,[["render",u]]);export{f as __pageData,k as default};
